def load_unverified_project_from_config(project_root: Path
    ) ->UnverifiedProjectModel:
    config = configparser.ConfigParser()
    config_path = project_root / PROJECT_CONFIG
    config.read(config_path)

    if PROJECT_CONFIG_SECTION not in config.sections():
        raise SafetyError("No project configuration found.")

    section = config[PROJECT_CONFIG_SECTION]
    project_id = section.get(PROJECT_CONFIG_ID)
    project_url = section.get(PROJECT_CONFIG_URL)
    project_name = section.get(PROJECT_CONFIG_NAME)

    if not project_id:
        raise SafetyError("Project ID not found in configuration.")

    return UnverifiedProjectModel(id=project_id, url_path=project_url, name=project_name)


def process_files(paths: Dict[str, Set[Path]], config: Optional[ConfigModel
    ]=None) ->Generator[Tuple[Path, InspectableFile], None, None]:
    for file_type, file_paths in paths.items():
        for file_path in file_paths:
            try:
                inspectable_file = InspectableFileContext.create_inspectable_file(
                    file_path=file_path, file_type=FileType(file_type), config=config)
                yield file_path, inspectable_file
            except Exception:
                LOG.debug(f"Could not process file {file_path}", exc_info=True)
                continue
